-- 5. OPUS — SAT_COMMON_ADDRESS   [Implemented]
-- HASHDIFF of stitch_kyc_common_address (6 tables) (stg2_kyc_common_address) also hashes
-- CAREOFNAME, which this satellite does not store (a shared stage feeding several
-- satellites). A change in only those columns gives a new HASHDIFF and so a NEW ROW WITH
-- AN UNCHANGED PAYLOAD here -- breaks DM-H2; see DM-H2 (a) unchanged_payload_reinserts.
-- The HASHDIFF cannot be recomputed from the satellite row. HASHDIFF column HASHDIFF.
-- Recomputed exactly as automate_dv 0.11.5 / sat_multi_source computes it, from the
-- payload stored on the same row. A match proves every payload change changes the
-- HASHDIFF, which is what drives a new row. standard satellite, sat_multi_source; PK
-- LOCATION_HKEY; 2 RECORD_SOURCE group(s): stitch_common_address (5 tables) [11 col(s)],
-- stitch_kyc_common_address (6 tables) [11 col(s)].
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'OPUS' as project, 'SAT_COMMON_ADDRESS' as satellite, 'stitch_common_address (5 tables)' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(ADDRESSLINE1 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ADDRESSLINE2 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ADDRESSLINE3 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(BUILDINGNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(COUNTRYCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(COUNTRYNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DOORNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POSTALCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(STATENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(STREETNAME AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(ADDRESSLINE1 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ADDRESSLINE2 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ADDRESSLINE3 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(BUILDINGNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(CITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(COUNTRYCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(COUNTRYNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DOORNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(POSTALCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(STATENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(STREETNAME AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(LOCATION_HKEY, 'HEX'), null)) within group (order by LOCATION_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS
 where (regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_ADDRESS_EXTN|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER|OPUS_CP_ADDRESSES)(, (OPUS_AZBJ_ADDRESS_EXTN|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER|OPUS_CP_ADDRESSES))*$'));

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct LOCATION_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_ADDRESS_EXTN|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER|OPUS_CP_ADDRESSES)(, (OPUS_AZBJ_ADDRESS_EXTN|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER|OPUS_CP_ADDRESSES))*$') order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_COMMON_ADDRESS' and record_source = 'stitch_common_address (5 tables)'
),
g1_t0 as (  -- stitch source OPUS_AZBJ_ADDRESS_EXTN
    select distinct (nullif(trim("ADD_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("ADDRESS_LINE6"::varchar), '')))), '') as addressline2,
           nullif(trim(to_varchar((nullif(trim("ADDRESS_LINE7"::varchar), '')))), '') as addressline3,
           nullif(trim(to_varchar((nullif(trim("BUILDING_NAME"::varchar), '')))), '') as buildingname,
           nullif(trim(to_varchar((nullif(trim("RESIDENCE_COUNTRY"::varchar), '')))), '') as countryname,
           nullif(trim(to_varchar((nullif(trim("DOOR_NO"::varchar), '')))), '') as doornumber,
           nullif(trim(to_varchar((nullif(trim("PLOT_STREET_NO"::varchar), '')))), '') as streetname,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_ADDRESS_EXTN
     where (nullif(trim("ADD_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("ADD_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t1 as (  -- stitch source OPUS_BJAZ_CLM_SUPP_EXTN
    select distinct (nullif(trim("BILLING_LOC"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("PARENT_CO_ADD_LINE1"::varchar), '')))), '') as addressline1,
           nullif(trim(to_varchar((nullif(trim("PARENT_CO_ADD_LINE2"::varchar), '')))), '') as addressline2,
           nullif(trim(to_varchar((nullif(trim("PARENT_CO_ADD_LINE3"::varchar), '')))), '') as addressline3,
           nullif(trim(to_varchar((nullif(trim("COUNTRY_CODE"::varchar), '')))), '') as countrycode,
           nullif(trim(to_varchar((nullif(trim("COUNTRY"::varchar), '')))), '') as countryname,
           nullif(trim(to_varchar((nullif(trim("BILLING_STATE"::varchar), '')))), '') as statename,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN
     where (nullif(trim("BILLING_LOC"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("BILLING_LOC"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t3 as (  -- stitch source OPUS_BJAZ_PINCODE
    select distinct (nullif(trim("PINCODE"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("CITY"::varchar), '')))), '') as city,
           nullif(trim(to_varchar((nullif(trim("STATUS"::varchar), '')))), '') as postalcode,
           nullif(trim(to_varchar((nullif(trim("STATE"::varchar), '')))), '') as statename,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE
     where (nullif(trim("PINCODE"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("PINCODE"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t4 as (  -- stitch source OPUS_BJAZ_PINCODE_MASTER
    select distinct (nullif(trim("PINCODE"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("CITY"::varchar), '')))), '') as city,
           nullif(trim(to_varchar((nullif(trim("STATE"::varchar), '')))), '') as statename,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_PINCODE_MASTER
     where (nullif(trim("PINCODE"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("PINCODE"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t5 as (  -- stitch source OPUS_CP_ADDRESSES
    select distinct (nullif(trim("ADD_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("ADDRESS_LINE1"::varchar), '')))), '') as addressline1,
           nullif(trim(to_varchar((nullif(trim("ADDRESS_LINE2"::varchar), '')))), '') as addressline2,
           nullif(trim(to_varchar((nullif(trim("ADDRESS_LINE3"::varchar), '')))), '') as addressline3,
           nullif(trim(to_varchar((nullif(trim("COUNTRY_CODE"::varchar), '')))), '') as countrycode,
           nullif(trim(to_varchar((nullif(trim("POSTCODE"::varchar), '')))), '') as postalcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_ADDRESSES
     where (nullif(trim("ADD_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || (((nullif(trim("ADD_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
k1 as (
    select parent_bk from g1_t0
    union
    select parent_bk from g1_t1
    union
    select parent_bk from g1_t3
    union
    select parent_bk from g1_t4
    union
    select parent_bk from g1_t5
),
st1 as (  -- stitch_common_address recomputed from RAW (same coalesce / priority as the stitch macro)
    select ak.parent_bk,
           coalesce(g1_t1.addressline1, g1_t5.addressline1) as addressline1,
           coalesce(g1_t0.addressline2, g1_t1.addressline2, g1_t5.addressline2) as addressline2,
           coalesce(g1_t0.addressline3, g1_t1.addressline3, g1_t5.addressline3) as addressline3,
           g1_t0.buildingname as buildingname,
           coalesce(g1_t3.city, g1_t4.city) as city,
           coalesce(g1_t1.countrycode, g1_t5.countrycode) as countrycode,
           coalesce(g1_t0.countryname, g1_t1.countryname) as countryname,
           g1_t0.doornumber as doornumber,
           coalesce(g1_t3.postalcode, g1_t5.postalcode) as postalcode,
           coalesce(g1_t1.statename, g1_t3.statename, g1_t4.statename) as statename,
           g1_t0.streetname as streetname,
           array_to_string(array_construct_compact(
               case when g1_t0.parent_bk is not null then 'OPUS_AZBJ_ADDRESS_EXTN' end,
               case when g1_t1.parent_bk is not null then 'OPUS_BJAZ_CLM_SUPP_EXTN' end,
               case when g1_t3.parent_bk is not null then 'OPUS_BJAZ_PINCODE' end,
               case when g1_t4.parent_bk is not null then 'OPUS_BJAZ_PINCODE_MASTER' end,
               case when g1_t5.parent_bk is not null then 'OPUS_CP_ADDRESSES' end
           ), ', ') as record_source,
           greatest_ignore_nulls(g1_t0.inc_job_updated_at, g1_t1.inc_job_updated_at, g1_t3.inc_job_updated_at, g1_t4.inc_job_updated_at, g1_t5.inc_job_updated_at) as inc_job_updated_at
      from k1 ak
      left join g1_t0 on g1_t0.parent_bk = ak.parent_bk
      left join g1_t1 on g1_t1.parent_bk = ak.parent_bk
      left join g1_t3 on g1_t3.parent_bk = ak.parent_bk
      left join g1_t4 on g1_t4.parent_bk = ak.parent_bk
      left join g1_t5 on g1_t5.parent_bk = ak.parent_bk
    qualify row_number() over (partition by ak.parent_bk order by g1_t0.addressline2 nulls last, g1_t0.addressline3 nulls last, g1_t0.buildingname nulls last, g1_t0.countryname nulls last, g1_t0.doornumber nulls last, g1_t0.streetname nulls last, g1_t1.addressline1 nulls last, g1_t1.addressline2 nulls last, g1_t1.addressline3 nulls last, g1_t1.countrycode nulls last, g1_t1.countryname nulls last, g1_t1.statename nulls last, g1_t3.city nulls last, g1_t3.postalcode nulls last, g1_t3.statename nulls last, g1_t4.city nulls last, g1_t4.statename nulls last, g1_t5.addressline1 nulls last, g1_t5.addressline2 nulls last, g1_t5.addressline3 nulls last, g1_t5.countrycode nulls last, g1_t5.postalcode nulls last) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stitch_common_address
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || st.parent_bk AS VARCHAR))), '')) as hkey,
               st.inc_job_updated_at as ldts,
               to_varchar(st.addressline1) as ADDRESSLINE1,
               to_varchar(st.addressline2) as ADDRESSLINE2,
               to_varchar(st.addressline3) as ADDRESSLINE3,
               to_varchar(st.buildingname) as BUILDINGNAME,
               to_varchar(st.city) as CITY,
               to_varchar(st.countrycode) as COUNTRYCODE,
               to_varchar(st.countryname) as COUNTRYNAME,
               to_varchar(st.doornumber) as DOORNUMBER,
               to_varchar(st.postalcode) as POSTALCODE,
               to_varchar(st.statename) as STATENAME,
               to_varchar(st.streetname) as STREETNAME
          from st1 st
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select LOCATION_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS
     where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_ADDRESS_EXTN|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER|OPUS_CP_ADDRESSES)(, (OPUS_AZBJ_ADDRESS_EXTN|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_PINCODE|OPUS_BJAZ_PINCODE_MASTER|OPUS_CP_ADDRESSES))*$') and LOCATION_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.ADDRESSLINE1 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.ADDRESSLINE2 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.ADDRESSLINE3 AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.BUILDINGNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.CITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.COUNTRYCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.COUNTRYNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.DOORNUMBER AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.POSTALCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.STATENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.STREETNAME AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'OPUS', 'SAT_COMMON_ADDRESS', 'stitch_common_address (5 tables)',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s2 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct LOCATION_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_COMMON_ADDRESS where regexp_like(RECORD_SOURCE, '^(OPUS_BJAZ_M_KYC_DRIVING_LICENCE|OPUS_BJAZ_M_KYC_GSTN|OPUS_BJAZ_M_KYC_VOTER|OPUS_BJAZ_T_CKYC_PERSONAL_DTLS|OPUS_BJAZ_T_EKYC|OPUS_BJAZ_T_KYC_OCR)(, (OPUS_BJAZ_M_KYC_DRIVING_LICENCE|OPUS_BJAZ_M_KYC_GSTN|OPUS_BJAZ_M_KYC_VOTER|OPUS_BJAZ_T_CKYC_PERSONAL_DTLS|OPUS_BJAZ_T_EKYC|OPUS_BJAZ_T_KYC_OCR))*$') order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_COMMON_ADDRESS' and record_source = 'stitch_kyc_common_address (6 tables)'
),
g2_t0 as (  -- stitch source OPUS_BJAZ_M_KYC_DRIVING_LICENCE
    select distinct case when nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), ''), '') end as parent_bk,
           nullif(trim(to_varchar(upper((nullif(trim("ADDRESS"::varchar), ''))))), '') as addressline1,
           nullif(trim(to_varchar(upper((nullif(trim("ZIP_CODE"::varchar), ''))))), '') as postalcode,
           nullif(trim(to_varchar(upper((nullif(trim("STATE"::varchar), ''))))), '') as statename,
           nullif(trim(to_varchar(cast(null as varchar))), '') as careofname,
           (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_DRIVING_LICENCE
     where case when nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), ''), '') end is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((case when nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("ADDRESS"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("ZIP_CODE"::varchar), ''))))), ''), '') end)) AS VARCHAR))), '')) in (select hkey from s2)
),
g2_t1 as (  -- stitch source OPUS_BJAZ_M_KYC_GSTN
    select distinct case when nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), ''), '') end as parent_bk,
           nullif(trim(to_varchar(upper((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), '') as addressline1,
           (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_GSTN
     where case when nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), ''), '') end is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((case when nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("BUSINESS_PLACE"::varchar), ''))))), ''), '') end)) AS VARCHAR))), '')) in (select hkey from s2)
),
g2_t2 as (  -- stitch source OPUS_BJAZ_M_KYC_VOTER
    select distinct case when nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("PART_NAME"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("DISTRICT"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') end as parent_bk,
           nullif(trim(to_varchar(upper((nullif(trim("STATE"::varchar), ''))))), '') as statename,
           (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_VOTER
     where case when nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("PART_NAME"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("DISTRICT"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') end is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((case when nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("PART_NAME"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("DISTRICT"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("STATE"::varchar), ''))))), ''), '') end)) AS VARCHAR))), '')) in (select hkey from s2)
),
g2_t3 as (  -- stitch source OPUS_BJAZ_T_CKYC_PERSONAL_DTLS
    select distinct case when nullif(upper(trim(to_varchar((nullif(trim("CORRES_CITY"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_COUNTRY"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE1"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE2"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE3"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_PIN"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_STATE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE1"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE2"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE3"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_CITY"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_DIST"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_PIN"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_COUNTRY"::varchar), ''))))), ''), '') end as parent_bk,
           nullif(trim(to_varchar(upper((nullif(trim("CORRES_LINE1"::varchar), ''))))), '') as addressline1,
           nullif(trim(to_varchar(upper((nullif(trim("CORRES_LINE2"::varchar), ''))))), '') as addressline2,
           nullif(trim(to_varchar(upper((nullif(trim("CORRES_LINE3"::varchar), ''))))), '') as addressline3,
           nullif(trim(to_varchar(upper((nullif(trim("CORRES_CITY"::varchar), ''))))), '') as city,
           nullif(trim(to_varchar(upper((nullif(trim("CORRES_COUNTRY"::varchar), ''))))), '') as countryname,
           nullif(trim(to_varchar(upper((nullif(trim("CORRES_PIN"::varchar), ''))))), '') as postalcode,
           nullif(trim(to_varchar(upper((nullif(trim("CORRES_STATE"::varchar), ''))))), '') as statename,
           (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_CKYC_PERSONAL_DTLS
     where case when nullif(upper(trim(to_varchar((nullif(trim("CORRES_CITY"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_COUNTRY"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE1"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE2"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE3"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_PIN"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_STATE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE1"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE2"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE3"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_CITY"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_DIST"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_PIN"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_COUNTRY"::varchar), ''))))), ''), '') end is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_LOCATION|' || ((case when nullif(upper(trim(to_varchar((nullif(trim("CORRES_CITY"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_COUNTRY"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE1"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE2"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE3"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_PIN"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("CORRES_STATE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE1"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE2"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_LINE3"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_CITY"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_DIST"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_PIN"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("CORRES_COUNTRY"::varchar), ''))))), ''), '') end)) AS VARCHAR))), '')) in (select hkey from s2)
),
g2_t4 as (  -- stitch source OPUS_BJAZ_T_CKYC_PERSONAL_DTLS
    select distinct case when nullif(upper(trim(to_varchar((nullif(trim("JURI_CITY"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("JURI_COUNTRY"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("JURI_LINE1"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("JURI_LINE2"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("JURI_LINE3"::varchar), ''))))), '') is not null or nullif(upper(trim(to_varchar((nullif(trim("JURI_STATE"::varchar), ''))))), '') is not null then coalesce(nullif(upper(trim(to_varchar((nullif(trim("JURI_LINE1"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("JURI_LINE2"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("JURI_LINE3"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("JURI_CITY"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("JURI_DIST"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("JURI_STATE"::varchar), ''))))), ''), '') || '|' || coalesce(nullif(upper(trim(to_varchar((nullif(trim("JURI_COUNTRY"::varchar), ''))))), ''), '') end as parent_bk,
           nullif(trim(to_varchar(upper((nullif(trim("JURI_LINE1"::varchar), ''))))), '') as addressline1,
           nullif(trim(to_varchar(upper((nullif(trim("JURI_LINE2"::varchar), ''))))), '') as addressline2,
           nullif(trim(to_varchar(upper((nullif(trim("JURI_LINE3"::varchar), ''))))), '') as addressline3,
           nullif(trim(to_varchar(upper((nullif(trim("JURI_CITY"::varchar), ''))))), '') as city,
           nullif(trim(to_varchar(upper((nullif(trim("JURI_COUNTRY"::varchar), ''))))), '') as countryname,
           nullif(trim(to_varchar(upper((nullif(trim("JURI_STATE"::varchar), ''))))), '') as statename,
           (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as inc_job_updated_at
