    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_LNK_ROLE_PROVIDER where RECORD_SOURCE = 'OPUS_BJAZ_HM_HOSPITAL_MASTER' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
