     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_LNK_ROLE_PROVIDER' and record_source = 'OPUS_BJAZ_HM_HOSPITAL_MASTER'
),
