    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION
     where RECORD_SOURCE = 'OPUS' and PARTY_HKEY in (select hkey from s15)
     group by 1, 2
),
x15 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.PASSPORTNUMBER AS VARCHAR))), ''), '^^'))) as raw_hash
      from e15 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'OPUS', 'SAT_PARTY_IDENTIFICATION', 'OPUS_BJAZ_M_KYC_PASSPORT',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n15 n full outer join x15 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s16 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION where RECORD_SOURCE = 'OPUS' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_IDENTIFICATION' and record_source = 'OPUS_BJAZ_M_KYC_VOTER'
),
e16 as (  -- expected value(s) at the latest RAW load timestamp per key
    select hkey, max(VOTERIDNUMBER) as VOTERIDNUMBER
      from (
        -- via stg_partner__bjaz_m_kyc_voter
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif('VOTER:' || upper(trim(coalesce((nullif(trim("VOTER_NUMBER"::varchar), '')),''))), 'VOTER:')) AS VARCHAR))), '')) as hkey,
               (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as ldts,
               to_varchar((nullif(trim("VOTER_NUMBER"::varchar), ''))) as VOTERIDNUMBER
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_M_KYC_VOTER
      )
     where hkey in (select hkey from s16) and ldts is not null
     group by hkey
),
n16 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTIFICATION
     where RECORD_SOURCE = 'OPUS' and PARTY_HKEY in (select hkey from s16)
     group by 1, 2
),
x16 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(IFNULL(NULLIF(UPPER(TRIM(CAST(e.VOTERIDNUMBER AS VARCHAR))), ''), '^^'))) as raw_hash
      from e16 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'OPUS', 'SAT_PARTY_IDENTIFICATION', 'OPUS_BJAZ_M_KYC_VOTER',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n16 n full outer join x16 x on x.hkey = n.hkey and x.cdk = n.cdk;



----------------------------------------------------------------------------------------
-- 30. OPUS — SAT_PARTY_IDENTITY   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. standard satellite,
-- sat_multi_source; PK PARTY_HKEY; 9 RECORD_SOURCE group(s): stitch_party_identity (19
-- tables) [17 col(s)], OPUS_BJAZ_T_CKYC_PERSONAL_DTLS [9 col(s)],
-- OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS [4 col(s)], OPUS_BJAZ_T_CKYC_SEARCH [3 col(s)],
-- OPUS_BJAZ_T_EKYC [3 col(s)], OPUS_BJAZ_T_KYC_AUTH [3 col(s)], OPUS_BJAZ_T_KYC_DETAILS
-- [3 col(s)], OPUS_BJAZ_T_KYC_INCOMING [4 col(s)], OPUS_BJAZ_T_KYC_OCR [5 col(s)].
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'OPUS' as project, 'SAT_PARTY_IDENTITY' as satellite, '9 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(AGE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DATEOFBIRTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DATEOFDEATH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(FIRSTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(GENDERCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LASTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MIDDLENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NAMESUFFIX AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NATIONALITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYDISPLAYNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYFULLNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYLEGALNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYSHORTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYTYPECODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PLACEOFBIRTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SALUTATION AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(AGE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DATEOFBIRTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DATEOFDEATH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(FIRSTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(GENDERCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(LASTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MIDDLENAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NAMESUFFIX AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NATIONALITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYDISPLAYNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYFULLNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYLEGALNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYSHORTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PARTYTYPECODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(PLACEOFBIRTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SALUTATION AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
 where (regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BA_HCP_DT_MEM|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_CTNGY_FF_DTLS_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HLT_ENSURE_MEM_DTLS|OPUS_BJAZ_HM_HOSPITAL_MASTER|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_INTERMEDIARY|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_BJAZ_STARPKG_FF_DTLS|OPUS_CP_PARTNERS|OPUS_OCP_INTERESTED_PARTIES)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BA_HCP_DT_MEM|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_CTNGY_FF_DTLS_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HLT_ENSURE_MEM_DTLS|OPUS_BJAZ_HM_HOSPITAL_MASTER|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_INTERMEDIARY|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_BJAZ_STARPKG_FF_DTLS|OPUS_CP_PARTNERS|OPUS_OCP_INTERESTED_PARTIES))*$')) or (RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS') or (RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_REL_PERSION_DTLS') or (RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_SEARCH') or (RECORD_SOURCE = 'OPUS_BJAZ_T_EKYC') or (RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_AUTH') or (RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_DETAILS') or (RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_INCOMING') or (RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_OCR');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BA_HCP_DT_MEM|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_CTNGY_FF_DTLS_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HLT_ENSURE_MEM_DTLS|OPUS_BJAZ_HM_HOSPITAL_MASTER|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_INTERMEDIARY|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_BJAZ_STARPKG_FF_DTLS|OPUS_CP_PARTNERS|OPUS_OCP_INTERESTED_PARTIES)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BA_HCP_DT_MEM|OPUS_BJAZ_CLM_SUPP_EXTN|OPUS_BJAZ_CTNGY_FF_DTLS_EXTN|OPUS_BJAZ_CTNGY_GC_MEM_DATA|OPUS_BJAZ_CTNGY_PA_MEM_DTLS|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HLT_ENSURE_MEM_DTLS|OPUS_BJAZ_HM_HOSPITAL_MASTER|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_INTERMEDIARY|OPUS_BJAZ_PA_DETL_EXTN|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_BJAZ_STARPKG_FF_DTLS|OPUS_CP_PARTNERS|OPUS_OCP_INTERESTED_PARTIES))*$') order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_IDENTITY' and record_source = 'stitch_party_identity (19 tables)'
),
g1_t0 as (  -- stitch source OPUS_AZBJ_PARTNER_EXTN
    select distinct (nullif(trim("PART_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("STATUS"::varchar), '')))), '') as partystatus,
           nullif(trim(to_varchar((nullif(trim("PLACE_OF_BIRTH"::varchar), '')))), '') as placeofbirth,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
     where (nullif(trim("PART_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PART_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t1 as (  -- stitch source OPUS_BA_HCP_DT_MEM
    select distinct (nullif(trim("PART_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("MEMBER_NAME"::varchar), '')))), '') as partyfullname,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BA_HCP_DT_MEM
     where (nullif(trim("PART_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PART_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t3 as (  -- stitch source OPUS_BJAZ_CLM_SUPP_EXTN
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("OWNERS_NAME"::varchar), '')))), '') as firstname,
           nullif(trim(to_varchar((nullif(trim("OWNERS_SUR_NAME"::varchar), '')))), '') as lastname,
           nullif(trim(to_varchar((nullif(trim("OWNERS_MIDDLE_NAME"::varchar), '')))), '') as middlename,
           nullif(trim(to_varchar((nullif(trim("OWNERS_FULL_NAME"::varchar), '')))), '') as partyfullname,
           nullif(trim(to_varchar((nullif(trim("MFG_CO_NAME"::varchar), '')))), '') as partylegalname,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CLM_SUPP_EXTN
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t5 as (  -- stitch source OPUS_BJAZ_CTNGY_FF_DTLS_EXTN
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("DOB"::timestamp_ntz))), '') as dateofbirth,
           nullif(trim(to_varchar((nullif(trim("GENDER"::varchar), '')))), '') as gendercode,
           nullif(trim(to_varchar((nullif(trim("MEMBER_NAME"::varchar), '')))), '') as partyfullname,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_FF_DTLS_EXTN
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t6 as (  -- stitch source OPUS_BJAZ_CTNGY_GC_MEM_DATA
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("AGE"::number))), '') as age,
           nullif(trim(to_varchar(("DATE_OF_BIRTH"::timestamp_ntz))), '') as dateofbirth,
           nullif(trim(to_varchar((nullif(trim("GENDER"::varchar), '')))), '') as gendercode,
           nullif(trim(to_varchar((nullif(trim("MEMBER_NAME"::varchar), '')))), '') as partyfullname,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_GC_MEM_DATA
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t7 as (  -- stitch source OPUS_BJAZ_CTNGY_PA_MEM_DTLS
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("AGE"::number))), '') as age,
           nullif(trim(to_varchar(("DOB"::timestamp_ntz))), '') as dateofbirth,
           nullif(trim(to_varchar((nullif(trim("GENDER"::varchar), '')))), '') as gendercode,
           nullif(trim(to_varchar((nullif(trim("LAST_NAME"::varchar), '')))), '') as lastname,
           nullif(trim(to_varchar((nullif(trim("MIDDLE_NAME"::varchar), '')))), '') as middlename,
           nullif(trim(to_varchar((nullif(trim("MEMBER_NAME"::varchar), '')))), '') as partyfullname,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_CTNGY_PA_MEM_DTLS
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t8 as (  -- stitch source OPUS_BJAZ_EC_MEM_DTLS_EXTN
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("AGE"::number))), '') as age,
           nullif(trim(to_varchar(("DATE_OF_BIRTH"::timestamp_ntz))), '') as dateofbirth,
           nullif(trim(to_varchar((nullif(trim("GENDER"::varchar), '')))), '') as gendercode,
           nullif(trim(to_varchar((nullif(trim("NAME"::varchar), '')))), '') as partyfullname,
           nullif(trim(to_varchar((nullif(trim("STATUS"::varchar), '')))), '') as partystatus,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t9 as (  -- stitch source OPUS_BJAZ_HCF_MEMBER_DTLS
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("AGE"::number))), '') as age,
           nullif(trim(to_varchar(("DATE_OF_BIRTH"::timestamp_ntz))), '') as dateofbirth,
           nullif(trim(to_varchar((nullif(trim("GENDER"::varchar), '')))), '') as gendercode,
           nullif(trim(to_varchar((nullif(trim("INSURED_NAME"::varchar), '')))), '') as partyfullname,
           nullif(trim(to_varchar((nullif(trim("COMPANY_NAME"::varchar), '')))), '') as partylegalname,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t10 as (  -- stitch source OPUS_BJAZ_HC_PART_EXTN
    select distinct (nullif(trim("PART_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("AGE"::number))), '') as age,
           nullif(trim(to_varchar(("DATE_OF_BIRTH"::timestamp_ntz))), '') as dateofbirth,
           nullif(trim(to_varchar((nullif(trim("SEX"::varchar), '')))), '') as gendercode,
           nullif(trim(to_varchar((nullif(trim("MEMBER_NAME"::varchar), '')))), '') as partyfullname,
           nullif(trim(to_varchar((nullif(trim("STATUS"::varchar), '')))), '') as partystatus,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HC_PART_EXTN
     where (nullif(trim("PART_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PART_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t11 as (  -- stitch source OPUS_BJAZ_HLT_ENSURE_MEM_DTLS
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("AGE"::number))), '') as age,
           nullif(trim(to_varchar(("DATE_OF_BIRTH"::timestamp_ntz))), '') as dateofbirth,
           nullif(trim(to_varchar((nullif(trim("GENDER"::varchar), '')))), '') as gendercode,
           nullif(trim(to_varchar((nullif(trim("NAME"::varchar), '')))), '') as partyfullname,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HLT_ENSURE_MEM_DTLS
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t12 as (  -- stitch source OPUS_BJAZ_HM_HOSPITAL_MASTER
    select distinct (nullif(trim("HOSID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("BENNAME"::varchar), '')))), '') as partydisplayname,
           nullif(trim(to_varchar((nullif(trim("HOSPITAL_NAME"::varchar), '')))), '') as partyfullname,
