    select parent_bk from g1_t19
    union
    select parent_bk from g1_t20
    union
    select parent_bk from g1_t21
),
st1 as (  -- stitch_party_identity recomputed from RAW (same coalesce / priority as the stitch macro)
    select ak.parent_bk,
           coalesce(g1_t6.age, g1_t7.age, g1_t8.age, g1_t9.age, g1_t10.age, g1_t11.age, g1_t13.age, g1_t16.age, g1_t17.age, g1_t18.age, g1_t19.age) as age,
           coalesce(g1_t5.dateofbirth, g1_t6.dateofbirth, g1_t7.dateofbirth, g1_t8.dateofbirth, g1_t9.dateofbirth, g1_t10.dateofbirth, g1_t11.dateofbirth, g1_t13.dateofbirth, g1_t16.dateofbirth, g1_t17.dateofbirth, g1_t18.dateofbirth, g1_t19.dateofbirth, g1_t20.dateofbirth) as dateofbirth,
           g1_t20.dateofdeath as dateofdeath,
           coalesce(g1_t3.firstname, g1_t20.firstname) as firstname,
           coalesce(g1_t5.gendercode, g1_t6.gendercode, g1_t7.gendercode, g1_t8.gendercode, g1_t9.gendercode, g1_t10.gendercode, g1_t11.gendercode, g1_t13.gendercode, g1_t17.gendercode, g1_t18.gendercode, g1_t19.gendercode, g1_t20.gendercode) as gendercode,
           coalesce(g1_t3.lastname, g1_t7.lastname, g1_t20.lastname) as lastname,
           coalesce(g1_t3.middlename, g1_t7.middlename, g1_t20.middlename) as middlename,
           g1_t20.namesuffix as namesuffix,
           g1_t20.nationality as nationality,
