           coalesce(g1_t1.partyfullname, g1_t3.partyfullname, g1_t5.partyfullname, g1_t6.partyfullname, g1_t7.partyfullname, g1_t8.partyfullname, g1_t9.partyfullname, g1_t10.partyfullname, g1_t11.partyfullname, g1_t12.partyfullname, g1_t13.partyfullname, g1_t14.partyfullname, g1_t16.partyfullname, g1_t17.partyfullname, g1_t18.partyfullname, g1_t19.partyfullname, g1_t20.partyfullname, g1_t21.partyfullname) as partyfullname,
