    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n7 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
     where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_DETAILS' and PARTY_HKEY in (select hkey from s7)
     group by 1, 2
),
x7 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.DATEOFBIRTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PARTYDISPLAYNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PARTYFULLNAME AS VARCHAR))), ''), '^^')))) as raw_hash
      from e7 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'OPUS', 'SAT_PARTY_IDENTITY', 'OPUS_BJAZ_T_KYC_DETAILS',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n7 n full outer join x7 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s8 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_INCOMING' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_IDENTITY' and record_source = 'OPUS_BJAZ_T_KYC_INCOMING'
),
e8 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_t_kyc_incoming
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("SEARCH_CATEGORY"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("SEARCH_INPUT"::varchar), '')),''))), ':')) AS VARCHAR))), '')) as hkey,
               (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as ldts,
               to_varchar((nullif(trim("DOB"::varchar), ''))) as DATEOFBIRTH,
               to_varchar((nullif(trim("GENDER"::varchar), ''))) as GENDERCODE,
               to_varchar((nullif(trim("FULL_NAME"::varchar), ''))) as PARTYFULLNAME,
               to_varchar((nullif(trim("CUSTOMER_TYPE"::varchar), ''))) as PARTYTYPECODE
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_INCOMING
      )
     where hkey in (select hkey from s8) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n8 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
     where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_INCOMING' and PARTY_HKEY in (select hkey from s8)
     group by 1, 2
),
x8 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.DATEOFBIRTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.GENDERCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PARTYFULLNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PARTYTYPECODE AS VARCHAR))), ''), '^^')))) as raw_hash
      from e8 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'OPUS', 'SAT_PARTY_IDENTITY', 'OPUS_BJAZ_T_KYC_INCOMING',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n8 n full outer join x8 x on x.hkey = n.hkey and x.cdk = n.cdk;

insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s9 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_OCR' order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_IDENTITY' and record_source = 'OPUS_BJAZ_T_KYC_OCR'
),
e9 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stg_partner__bjaz_t_kyc_ocr
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (nullif(upper(trim(coalesce((nullif(trim("FIELD_TYPE"::varchar), '')),''))) || ':' || upper(trim(coalesce((nullif(trim("FIELD_VALUE"::varchar), '')),''))), ':')) AS VARCHAR))), '')) as hkey,
               (to_timestamp_ntz(regexp_replace("INC_JOB_UPDATED_AT"::varchar, '^Z[ ]*', ''))) as ldts,
               to_varchar((nullif(trim("DOB"::varchar), ''))) as DATEOFBIRTH,
               to_varchar((nullif(trim("GENDER"::varchar), ''))) as GENDERCODE,
               to_varchar((nullif(trim("SURNAME"::varchar), ''))) as LASTNAME,
               to_varchar((nullif(trim("NATIONALITY"::varchar), ''))) as NATIONALITY,
               to_varchar((nullif(trim("PLACE_OF_BIRTH"::varchar), ''))) as PLACEOFBIRTH
          from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_T_KYC_OCR
      )
     where hkey in (select hkey from s9) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n9 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_IDENTITY
     where RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_OCR' and PARTY_HKEY in (select hkey from s9)
     group by 1, 2
),
x9 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.DATEOFBIRTH AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.GENDERCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.LASTNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.NATIONALITY AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.PLACEOFBIRTH AS VARCHAR))), ''), '^^')))) as raw_hash
      from e9 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'OPUS', 'SAT_PARTY_IDENTITY', 'OPUS_BJAZ_T_KYC_OCR',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n9 n full outer join x9 x on x.hkey = n.hkey and x.cdk = n.cdk;



----------------------------------------------------------------------------------------
-- 31. OPUS — SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS   [Implemented]
-- HASHDIFF column HASHDIFF. Recomputed exactly as automate_dv 0.11.5 / sat_multi_source
-- computes it, from the payload stored on the same row. A match proves every payload
-- change changes the HASHDIFF, which is what drives a new row. standard satellite,
-- sat_multi_source; PK PARTY_HKEY; 3 RECORD_SOURCE group(s):
-- stitch_party_individual_demographics (8 tables) [10 col(s)],
-- OPUS_BJAZ_T_CKYC_PERSONAL_DTLS [3 col(s)], OPUS_BJAZ_T_KYC_OCR [1 col(s)].
----------------------------------------------------------------------------------------
-- SQL query (a) -- HASHDIFF integrity (all rows of this project)
select 'OPUS' as project, 'SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS' as satellite, '3 RECORD_SOURCEs sharing one HASHDIFF column list' as scope,
       count(*) as rows_checked,
       count_if(HASHDIFF is null) as null_hashdiff,
       count_if(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(ANNUALHOUSEHOLDINCOME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ANNUALINCOME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DESIGNATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(EDUCATIONALQUALIFICATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(FATHERNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MARITALSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NUMBEROFCHILDREN AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OCCUPATIONCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OCCUPATIONDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SPOUSENAME AS VARCHAR))), ''), '^^'))) AS BINARY(16))) as hashdiff_mismatch,
       array_slice(array_agg(iff(HASHDIFF <> CAST(MD5_BINARY(CONCAT_WS('||', IFNULL(NULLIF(UPPER(TRIM(CAST(ANNUALHOUSEHOLDINCOME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(ANNUALINCOME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(DESIGNATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(EDUCATIONALQUALIFICATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(FATHERNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(MARITALSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(NUMBEROFCHILDREN AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OCCUPATIONCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(OCCUPATIONDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(SPOUSENAME AS VARCHAR))), ''), '^^'))) AS BINARY(16)), to_varchar(PARTY_HKEY, 'HEX'), null)) within group (order by PARTY_HKEY), 0, 3) as mismatch_examples,
       iff(null_hashdiff = 0 and hashdiff_mismatch = 0, 'PASS', 'FAIL') as status
  from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS
 where (regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_CP_PARTNERS)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_CP_PARTNERS))*$')) or (RECORD_SOURCE = 'OPUS_BJAZ_T_CKYC_PERSONAL_DTLS') or (RECORD_SOURCE = 'OPUS_BJAZ_T_KYC_OCR');

-- SQL (b) -- CDC capture (run in BEFORE and in AFTER phase)
insert into BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT (run_id, phase, project, satellite, record_source, hkey, cdk, sat_rows, sat_max_ldts, raw_hash, captured_at)
with s1 as (  -- BEFORE: first 100 keys by hash; AFTER: exactly the keys captured BEFORE
    select hkey from (
        select distinct PARTY_HKEY as hkey from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_CP_PARTNERS)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_CP_PARTNERS))*$') order by hkey limit 100
    ) where $DM_H_PHASE = 'BEFORE'
    union
    select distinct hkey from BAGIC_PREPROD_CURATED_DB.BGIL_VALIDATION.DM_H_CDC_SNAPSHOT
     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS' and record_source = 'stitch_party_individual_demographics (8 tables)'
),
g1_t0 as (  -- stitch source OPUS_AZBJ_PARTNER_EXTN
    select distinct (nullif(trim("PART_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("FAMILY_MONTHLY_INCOME"::varchar), '')))), '') as annualhouseholdincome,
           nullif(trim(to_varchar((nullif(trim("EDUCATION"::varchar), '')))), '') as educationalqualification,
           nullif(trim(to_varchar((nullif(trim("FATHER_NAME"::varchar), '')))), '') as fathername,
           nullif(trim(to_varchar(("NO_OF_CHILDREN"::number))), '') as numberofchildren,
           nullif(trim(to_varchar((nullif(trim("OCCUPATION_DESC_GEN"::varchar), '')))), '') as occupationdescription,
           nullif(trim(to_varchar((nullif(trim("SPOUSE_NAME"::varchar), '')))), '') as spousename,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.AZBJ_PARTNER_EXTN
     where (nullif(trim("PART_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PART_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t3 as (  -- stitch source OPUS_BJAZ_EC_MEM_DTLS_EXTN
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("GROSS_INCOME"::number))), '') as annualincome,
           nullif(trim(to_varchar((nullif(trim("OCCUPATION"::varchar), '')))), '') as occupationcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_EC_MEM_DTLS_EXTN
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t4 as (  -- stitch source OPUS_BJAZ_HCF_MEMBER_DTLS
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("MONTHLY_INCOME"::number))), '') as annualincome,
           nullif(trim(to_varchar((nullif(trim("MEMBER_OCCUPATION"::varchar), '')))), '') as occupationcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HCF_MEMBER_DTLS
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t5 as (  -- stitch source OPUS_BJAZ_HC_PART_EXTN
    select distinct (nullif(trim("PART_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("OCCUPATION"::varchar), '')))), '') as occupationcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HC_PART_EXTN
     where (nullif(trim("PART_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PART_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t6 as (  -- stitch source OPUS_BJAZ_HM_MEMBER_DTLS
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("GROSS_INCOME"::number))), '') as annualincome,
           nullif(trim(to_varchar((nullif(trim("DESIGNATION"::varchar), '')))), '') as designation,
           nullif(trim(to_varchar((nullif(trim("OCCUPATION"::varchar), '')))), '') as occupationcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_HM_MEMBER_DTLS
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t7 as (  -- stitch source OPUS_BJAZ_SH_MEM_DTLS_EXTN
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar(("GROSS_INCOME"::number))), '') as annualincome,
           nullif(trim(to_varchar((nullif(trim("OCCUPATION"::varchar), '')))), '') as occupationcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SH_MEM_DTLS_EXTN
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t8 as (  -- stitch source OPUS_BJAZ_SPP_MEMBER_DTLS
    select distinct (nullif(trim("PARTNER_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("MEMBER_OCCUPATION"::varchar), '')))), '') as occupationcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.BJAZ_SPP_MEMBER_DTLS
     where (nullif(trim("PARTNER_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PARTNER_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
g1_t9 as (  -- stitch source OPUS_CP_PARTNERS
    select distinct (nullif(trim("PART_ID"::varchar), '')) as parent_bk,
           nullif(trim(to_varchar((nullif(trim("MARITAL_STATUS"::varchar), '')))), '') as maritalstatus,
           nullif(trim(to_varchar((nullif(trim("OCCUPATION"::varchar), '')))), '') as occupationcode,
           ("INC_JOB_UPDATED_AT"::timestamp_ntz) as inc_job_updated_at
      from BAGIC_PREPROD_CURATED_DB.UTILS.CP_PARTNERS
     where (nullif(trim("PART_ID"::varchar), '')) is not null
       and MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || (((nullif(trim("PART_ID"::varchar), '')))) AS VARCHAR))), '')) in (select hkey from s1)
),
k1 as (
    select parent_bk from g1_t0
    union
    select parent_bk from g1_t3
    union
    select parent_bk from g1_t4
    union
    select parent_bk from g1_t5
    union
    select parent_bk from g1_t6
    union
    select parent_bk from g1_t7
    union
    select parent_bk from g1_t8
    union
    select parent_bk from g1_t9
),
st1 as (  -- stitch_party_individual_demographics recomputed from RAW (same coalesce / priority as the stitch macro)
    select ak.parent_bk,
           g1_t0.annualhouseholdincome as annualhouseholdincome,
           coalesce(g1_t3.annualincome, g1_t4.annualincome, g1_t6.annualincome, g1_t7.annualincome) as annualincome,
           g1_t6.designation as designation,
           g1_t0.educationalqualification as educationalqualification,
           g1_t0.fathername as fathername,
           g1_t9.maritalstatus as maritalstatus,
           g1_t0.numberofchildren as numberofchildren,
           coalesce(g1_t3.occupationcode, g1_t4.occupationcode, g1_t5.occupationcode, g1_t6.occupationcode, g1_t7.occupationcode, g1_t8.occupationcode, g1_t9.occupationcode) as occupationcode,
           g1_t0.occupationdescription as occupationdescription,
           g1_t0.spousename as spousename,
           array_to_string(array_construct_compact(
               case when g1_t0.parent_bk is not null then 'OPUS_AZBJ_PARTNER_EXTN' end,
               case when g1_t3.parent_bk is not null then 'OPUS_BJAZ_EC_MEM_DTLS_EXTN' end,
               case when g1_t4.parent_bk is not null then 'OPUS_BJAZ_HCF_MEMBER_DTLS' end,
               case when g1_t5.parent_bk is not null then 'OPUS_BJAZ_HC_PART_EXTN' end,
               case when g1_t6.parent_bk is not null then 'OPUS_BJAZ_HM_MEMBER_DTLS' end,
               case when g1_t7.parent_bk is not null then 'OPUS_BJAZ_SH_MEM_DTLS_EXTN' end,
               case when g1_t8.parent_bk is not null then 'OPUS_BJAZ_SPP_MEMBER_DTLS' end,
               case when g1_t9.parent_bk is not null then 'OPUS_CP_PARTNERS' end
           ), ', ') as record_source,
           greatest_ignore_nulls(g1_t0.inc_job_updated_at, g1_t3.inc_job_updated_at, g1_t4.inc_job_updated_at, g1_t5.inc_job_updated_at, g1_t6.inc_job_updated_at, g1_t7.inc_job_updated_at, g1_t8.inc_job_updated_at, g1_t9.inc_job_updated_at) as inc_job_updated_at
      from k1 ak
      left join g1_t0 on g1_t0.parent_bk = ak.parent_bk
      left join g1_t3 on g1_t3.parent_bk = ak.parent_bk
      left join g1_t4 on g1_t4.parent_bk = ak.parent_bk
      left join g1_t5 on g1_t5.parent_bk = ak.parent_bk
      left join g1_t6 on g1_t6.parent_bk = ak.parent_bk
      left join g1_t7 on g1_t7.parent_bk = ak.parent_bk
      left join g1_t8 on g1_t8.parent_bk = ak.parent_bk
      left join g1_t9 on g1_t9.parent_bk = ak.parent_bk
    qualify row_number() over (partition by ak.parent_bk order by g1_t0.annualhouseholdincome nulls last, g1_t0.educationalqualification nulls last, g1_t0.fathername nulls last, g1_t0.numberofchildren nulls last, g1_t0.occupationdescription nulls last, g1_t0.spousename nulls last, g1_t3.annualincome nulls last, g1_t3.occupationcode nulls last, g1_t4.annualincome nulls last, g1_t4.occupationcode nulls last, g1_t5.occupationcode nulls last, g1_t6.annualincome nulls last, g1_t6.designation nulls last, g1_t6.occupationcode nulls last, g1_t7.annualincome nulls last, g1_t7.occupationcode nulls last, g1_t8.occupationcode nulls last, g1_t9.maritalstatus nulls last, g1_t9.occupationcode nulls last) = 1
),
e1 as (  -- expected value(s) at the latest RAW load timestamp per key
    select *
      from (
        -- via stitch_party_individual_demographics
        select MD5_BINARY(NULLIF(UPPER(TRIM(CAST('HUB_PARTY|' || st.parent_bk AS VARCHAR))), '')) as hkey,
               st.inc_job_updated_at as ldts,
               to_varchar(st.annualhouseholdincome) as ANNUALHOUSEHOLDINCOME,
               to_varchar(st.annualincome) as ANNUALINCOME,
               to_varchar(st.designation) as DESIGNATION,
               to_varchar(st.educationalqualification) as EDUCATIONALQUALIFICATION,
               to_varchar(st.fathername) as FATHERNAME,
               to_varchar(st.maritalstatus) as MARITALSTATUS,
               to_varchar(st.numberofchildren) as NUMBEROFCHILDREN,
               to_varchar(st.occupationcode) as OCCUPATIONCODE,
               to_varchar(st.occupationdescription) as OCCUPATIONDESCRIPTION,
               to_varchar(st.spousename) as SPOUSENAME
          from st1 st
      )
     where hkey in (select hkey from s1) and ldts is not null
    qualify rank() over (partition by hkey order by ldts desc) = 1
),
n1 as (  -- satellite history per sampled key
    select PARTY_HKEY as hkey, '' as cdk, count(*) as sat_rows, max(LOAD_DATETIME) as sat_max_ldts
      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS
     where regexp_like(RECORD_SOURCE, '^(OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_CP_PARTNERS)(, (OPUS_AZBJ_PARTNER_EXTN|OPUS_BJAZ_EC_MEM_DTLS_EXTN|OPUS_BJAZ_HCF_MEMBER_DTLS|OPUS_BJAZ_HC_PART_EXTN|OPUS_BJAZ_HM_MEMBER_DTLS|OPUS_BJAZ_SH_MEM_DTLS_EXTN|OPUS_BJAZ_SPP_MEMBER_DTLS|OPUS_CP_PARTNERS))*$') and PARTY_HKEY in (select hkey from s1)
     group by 1, 2
),
x1 as (  -- normalised RAW payload hash (UPPER / TRIM / '^^' like the HASHDIFF)
    select e.hkey, '' as cdk, min(md5(concat_ws('||', IFNULL(NULLIF(UPPER(TRIM(CAST(e.ANNUALHOUSEHOLDINCOME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.ANNUALINCOME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.DESIGNATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.EDUCATIONALQUALIFICATION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.FATHERNAME AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.MARITALSTATUS AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.NUMBEROFCHILDREN AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.OCCUPATIONCODE AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.OCCUPATIONDESCRIPTION AS VARCHAR))), ''), '^^'), IFNULL(NULLIF(UPPER(TRIM(CAST(e.SPOUSENAME AS VARCHAR))), ''), '^^')))) as raw_hash
      from e1 e group by 1, 2
)
select $DM_H_RUN, $DM_H_PHASE, 'OPUS', 'SAT_PARTY_INDIVIDUAL_DEMOGRAPHICS', 'stitch_party_individual_demographics (8 tables)',
       coalesce(n.hkey, x.hkey), coalesce(n.cdk, x.cdk), coalesce(n.sat_rows, 0), n.sat_max_ldts, x.raw_hash, current_timestamp()
  from n1 n full outer join x1 x on x.hkey = n.hkey and x.cdk = n.cdk;

