       and satellite = 'SAT_PARTY_VEHICLE_PRIOR_INSURANCE' and record_source = 'OPUS_BJAZ_HLT_ENSURE_MEM_DTLS'
),
e5 as (  -- expected value(s) at the latest RAW load timestamp per key
