      from BAGIC_PREPROD_CURATED_DB.BGIL_DATA_MODEL.SAT_PROVIDER_TARIFF
     where RECORD_SOURCE = 'OPUS_BJAZ_HM_HOSPITAL_MASTER' and PARTY_HKEY in (select hkey from s1)
