     where $DM_H_PHASE = 'AFTER' and run_id = $DM_H_RUN and phase = 'BEFORE'
       and satellite = 'SAT_AUG_KYC_LOCATION' and record_source = 'OPUS_BJAZ_M_KYC_VOTER'
